def compute(vars):
    price = vars["v1"]
    shares = vars["v2"]
    market_cap = price * shares

    return {
        "value": market_cap,
        "trace": {
            "price_per_share": price,
            "outstanding_shares": shares,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
